import React, { useMemo, useState } from "react";
import { Card, Select, Typography, Row, Col, Table, Tag, Space, Tooltip, Progress } from "antd";
import { BarChartOutlined, UserOutlined, StarFilled, FrownFilled, BookOutlined } from "@ant-design/icons";
import IBook from "../types/IBook";

interface StatsPageProps {
  books: IBook[];
}

const { Title, Text } = Typography;

const cardStyle = {
  borderRadius: 16,
  boxShadow: "0 4px 24px 0 rgba(0,0,0,0.10)",
  background: "var(--ant-primary-1, #fff)",
  padding: 32,
};

const statOptions = [
  { value: "authors", label: "Most Read Authors", icon: <BookOutlined /> },
  { value: "byPerson", label: "Books Selected by Person", icon: <UserOutlined /> },
  { value: "favorites", label: "Favorites Selected by Person", icon: <StarFilled /> },
  { value: "dislikes", label: "Dislikes Selected by Person", icon: <FrownFilled /> },
  { value: "avgPages", label: "Average Page Count of Book Selected", icon: <BarChartOutlined /> },
  { value: "listByPerson", label: "Books List by Person", icon: <BookOutlined /> },
];

const StatsPage: React.FC<StatsPageProps> = ({ books }) => {
  // Multi-select years
  const [selectedYears, setSelectedYears] = useState<string[]>([]);
  const [selectedStat, setSelectedStat] = useState<string>("authors");

  // All years present in the data
  const years = useMemo(
    () =>
      Array.from(new Set(books.map((b) => b.year).filter((y): y is number => typeof y === "number")))
        .sort((a, b) => a - b)
        .map(String),
    [books]
  );

  // Filter books by selected years (or all if none selected)
  const filteredBooks = useMemo(
    () =>
      selectedYears.length > 0
        ? books.filter((b) => b.year && selectedYears.includes(String(b.year)))
        : books,
    [books, selectedYears]
  );

  // Books selected by person
  const booksByPerson = useMemo(() => {
    const map: Record<string, IBook[]> = {};
    filteredBooks.forEach((b) => {
      if (b.picked_by) {
        if (!map[b.picked_by]) map[b.picked_by] = [];
        map[b.picked_by].push(b);
      }
    });
    return map;
  }, [filteredBooks]);

  // --- Chart Data Preparation ---
  const mostReadAuthors = useMemo(() => {
    const counts: Record<string, number> = {};
    filteredBooks.forEach((b) => {
      if (b.author) counts[b.author] = (counts[b.author] || 0) + 1;
    });
    return Object.entries(counts)
      .map(([author, count]) => ({ name: author, value: count }))
      .sort((a, b) => b.value - a.value);
  }, [filteredBooks]);

  const booksByPersonArr = useMemo(
    () =>
      Object.entries(booksByPerson)
        .map(([person, books]) => ({ name: person, value: books.length }))
        .sort((a, b) => b.value - a.value),
    [booksByPerson]
  );

  const favoritesByPersonArr = useMemo(() => {
    return Object.entries(booksByPerson)
      .map(([person, books]) => ({
        name: person,
        value: books.filter((b) => b.best_of).length,
      }))
      .sort((a, b) => b.value - a.value);
  }, [booksByPerson]);

  const dislikesByPersonArr = useMemo(() => {
    return Object.entries(booksByPerson)
      .map(([person, books]) => ({
        name: person,
        value: books.filter((b) => b.worst_of).length,
      }))
      .sort((a, b) => b.value - a.value);
  }, [booksByPerson]);

  const avgPagesByPersonArr = useMemo(() => {
    return Object.entries(booksByPerson)
      .map(([person, books]) => {
        const withPages = books.filter(b => typeof b.pages === 'number');
        const avg = withPages.length > 0 ? Math.round(withPages.reduce((sum, b) => sum + (b.pages || 0), 0) / withPages.length) : 0;
        return { name: person, value: avg };
      })
      .sort((a, b) => b.value - a.value);
  }, [booksByPerson]);

  // List of books selected per person (for the 'Books List by Person' stat)
  const booksListByPersonArr = useMemo(() => {
    return Object.entries(booksByPerson).map(([person, books]) => ({
      name: person,
      books: books.map((b) => b.title),
    }));
  }, [booksByPerson]);

  // --- Chart Renderers ---
  function renderBarChart(data: { name: string; value: number }[], color: string) {
    if (!data.length) return <Text type="secondary">No data for selection.</Text>;
    const max = Math.max(...data.map((d) => d.value), 1);
    return (
      <div style={{ margin: "24px 0" }}>
        {data.map((d) => (
          <div key={d.name} style={{ display: "flex", alignItems: "center", marginBottom: 8 }}>
            <div style={{ width: 140, fontWeight: 500 }}>{d.name}</div>
            <Progress
              percent={Math.round((d.value / max) * 100)}
              showInfo={false}
              strokeColor={color}
              style={{ flex: 1, margin: "0 12px" }}
            />
            <span style={{ minWidth: 32, textAlign: "right", fontVariantNumeric: "tabular-nums" }}>{d.value}</span>
          </div>
        ))}
      </div>
    );
  }

  // --- Stat Content Switcher ---
  let statContent: React.ReactNode = null;
  if (selectedStat === "authors") {
    statContent = (
      <>
        {renderBarChart(mostReadAuthors, "#722ed1")}
        <Table
          dataSource={mostReadAuthors}
          columns={[
            { title: "Author", dataIndex: "name", key: "name" },
            { title: "Books Read", dataIndex: "value", key: "value" },
          ]}
          pagination={false}
          rowKey="name"
          size="middle"
          bordered
          showHeader
        />
      </>
    );
  } else if (selectedStat === "byPerson") {
    statContent = (
      <>
        {renderBarChart(booksByPersonArr, "#faad14")}
        <Table
          dataSource={booksByPersonArr}
          columns={[
            { title: "Person", dataIndex: "name", key: "name" },
            { title: "Books Selected", dataIndex: "value", key: "value" },
          ]}
          pagination={false}
          rowKey="name"
          size="middle"
          bordered
          showHeader
        />
      </>
    );
  } else if (selectedStat === "favorites") {
    statContent = (
      <>
        {renderBarChart(favoritesByPersonArr, "#fadb14")}
        <Table
          dataSource={favoritesByPersonArr}
          columns={[
            { title: "Person", dataIndex: "name", key: "name" },
            { title: "Favorites Selected", dataIndex: "value", key: "value" },
          ]}
          pagination={false}
          rowKey="name"
          size="middle"
          bordered
          showHeader
        />
      </>
    );
  } else if (selectedStat === "dislikes") {
    statContent = (
      <>
        {renderBarChart(dislikesByPersonArr, "#ff4d4f")}
        <Table
          dataSource={dislikesByPersonArr}
          columns={[
            { title: "Person", dataIndex: "name", key: "name" },
            { title: "Dislikes Selected", dataIndex: "value", key: "value" },
          ]}
          pagination={false}
          rowKey="name"
          size="middle"
          bordered
          showHeader
        />
      </>
    );
  } else if (selectedStat === "avgPages") {
    statContent = (
      <>
        {renderBarChart(avgPagesByPersonArr, "#13c2c2")}
        <Table
          dataSource={avgPagesByPersonArr}
          columns={[
            { title: "Person", dataIndex: "name", key: "name" },
            { title: "Average Page Count", dataIndex: "value", key: "value" },
          ]}
          pagination={false}
          rowKey="name"
          size="middle"
          bordered
          showHeader
        />
      </>
    );
  } else if (selectedStat === "listByPerson") {
    statContent = (
      <Table
        dataSource={booksListByPersonArr}
        columns={[
          { title: "Person", dataIndex: "name", key: "name" },
          {
            title: "Books",
            dataIndex: "books",
            key: "books",
            render: (books: string[]) => (
              <Space wrap>
                {books.map((title, idx) => (
                  <Tooltip title={title} key={idx}>
                    <Tag
                      color="geekblue"
                      style={{ marginBottom: 4, fontSize: 14, borderRadius: 8, cursor: "pointer" }}
                    >
                      {title.length > 22 ? title.slice(0, 20) + "…" : title}
                    </Tag>
                  </Tooltip>
                ))}
              </Space>
            ),
          },
        ]}
        pagination={false}
        rowKey="name"
        size="middle"
        bordered
        showHeader
      />
    );
  }

  // Responsive column span
  const colSpan = { xs: 24, sm: 22, md: 20, lg: 18, xl: 16 };

  return (
    <Row justify="center" style={{ marginTop: 32, minHeight: "100vh", background: "var(--ant-primary-2, #f6f8fa)" }}>
      <Col {...colSpan}>
        <Card style={cardStyle}>
          <Space direction="vertical" size={36} style={{ width: "100%" }}>
            <Space align="center" style={{ width: "100%", justifyContent: "center" }}>
              <BarChartOutlined style={{ fontSize: 36, color: "#1890ff" }} />
              <Title level={1} style={{ margin: 0, color: "#222" }}>Book Club Stats</Title>
            </Space>
            <div style={{ marginBottom: 12, textAlign: "center" }}>
              <Text strong style={{ fontSize: 16, marginRight: 8 }}>Filter by year(s):</Text>
              <Select
                mode="multiple"
                allowClear
                placeholder="Select year(s)"
                style={{ minWidth: 220, maxWidth: 400, fontWeight: 500 }}
                value={selectedYears}
                onChange={setSelectedYears}
                options={years.map((y) => ({ value: y, label: y }))}
                size="large"
              />
            </div>
            <div style={{ marginBottom: 24, textAlign: "center" }}>
              <Text strong style={{ fontSize: 16, marginRight: 8 }}>Select stat to view:</Text>
              <Select
                value={selectedStat}
                onChange={setSelectedStat}
                options={statOptions.map(opt => ({ value: opt.value, label: <span>{opt.icon} {opt.label}</span> }))}
                style={{ minWidth: 260, fontWeight: 500 }}
                size="large"
              />
            </div>
            {statContent}
          </Space>
        </Card>
      </Col>
    </Row>
  );
};

export default StatsPage;
